8	// an identifier, a number, a closing `)` or `]` - it is division. The keywords
9	// are the identifiers that are not values, so the `/` after them opens a regex.
10	const VALUE_END = /[\w$)\]]$/;
11	const NOT_A_VALUE = /\b(return|typeof|instanceof|in|of|new|delete|void|case|do|else|yield|await)$/;
12	function opensRegex(code) {
13	  const before = code.replace(/\s+$/, '');
14	  if (before === '') return true;
15	  if (!VALUE_END.test(before)) return true;
16	  return NOT_A_VALUE.test(before);
17	}
18	
