20	// including string, template and regex literals - byte-for-byte intact.
21	// Literal-aware on purpose: a `//` inside "https://…" is not a comment, and
22	// dropping the rest of that line would corrupt real code (and could hide a
23	// genuine violation that follows on the same line). The same holds inside a
24	// regex, whose `"`, `'` and `` ` `` are pattern characters - reading one as a
25	// string's opening quote puts the scanner in string state for the rest of the
26	// file, where every later comment survives and every later string reads as code.
27	// Newlines inside block comments are kept so line numbers don't shift.
28	export function stripComments(source) {
29	  let out = '';
30	  let state = 'code'; // code | line | block | sq | dq | tpl | re | reClass
31	  // One frame per `${}` hole still open, innermost last, each holding the brace
32	  // depth reached inside it. A hole holds code, and that code may open a template
33	  // of its own, so the enclosing template is a place to return to rather than a
34	  // flag: without the stack the inner literal's backtick closed the outer one and
35	  // every character after it read inside-out.
36	  const holes = [];
37	  for (let i = 0; i < source.length; i++) {
38	    const c = source[i];
39	    const c2 = source[i + 1];
40	    if (state === 'code') {
41	      if (c === '/' && c2 === '/') { state = 'line'; i++; continue; }
42	      if (c === '/' && c2 === '*') { state = 'block'; i++; continue; }
43	      if (c === '/' && opensRegex(out)) state = 're';
44	      else if (c === "'") state = 'sq';
45	      else if (c === '"') state = 'dq';
46	      else if (c === '`') state = 'tpl';
47	      else if (holes.length && c === '{') holes[holes.length - 1].depth++;
48	      else if (holes.length && c === '}') {
49	        if (holes[holes.length - 1].depth === 0) { holes.pop(); state = 'tpl'; }
50	        else holes[holes.length - 1].depth--;
51	      }
52	      out += c;
53	    } else if (state === 're' || state === 'reClass') {
54	      // Inside a regex literal. A `/` inside a character class is a literal
55	      // slash, not the closing delimiter, so the class is tracked as its own
56	      // state rather than guessed at.
57	      out += c;
58	      if (c === '\\') { out += c2 ?? ''; i++; }
59	      else if (c === '\n') state = 'code'; // an unterminated regex was a division after all
60	      else if (state === 're' && c === '[') state = 'reClass';
61	      else if (state === 'reClass' && c === ']') state = 're';
62	      else if (state === 're' && c === '/') state = 'code';
63	    } else if (state === 'line') {
64	      if (c === '\n') { state = 'code'; out += c; }
65	    } else if (state === 'block') {
66	      if (c === '*' && c2 === '/') { state = 'code'; i++; }
67	      else if (c === '\n') out += c;
68	    } else {
69	      // Inside a string/template literal: copy through until the matching quote,
70	      // honoring backslash escapes so an escaped quote doesn't end it early.
71	      out += c;
72	      if (c === '\\') { out += c2 ?? ''; i++; }
73	      else if (state === 'tpl' && c === '$' && c2 === '{') {
74	        out += c2; i++;
75	        holes.push({ depth: 0 });
76	        state = 'code';
77	      } else if ((state === 'sq' && c === "'") || (state === 'dq' && c === '"') || (state === 'tpl' && c === '`')) {
78	        state = 'code';
79	      }
80	    }
81	  }
82	  return out;
83	}
