1	/* The festival planner's stylesheet: the Fringe planner's, plus a theme.
2	 *
3	 * The page IS the Fringe planner's board, so it imports that stylesheet whole
4	 * rather than copying 1,600 lines that would then drift. Everything below is
5	 * either a brand token redefined, a rule the second festival's *shape* needs
6	 * (five columns rather than thirty-one), or a component this page has and the
7	 * Fringe planner doesn't (the browse stage, the origin question).
8	 *
9	 * Theming is per genre: the page root carries `data-genre="<kind>"`, the
10	 * focused festival's `kind` from the registry, and each genre's block below
11	 * redefines the same handful of tokens, so two comedy festivals share one
12	 * palette. A genre with no block keeps the house palette plan.css defines.
13	 * The wordmark is ./festivals.js's.
14	 */
15	@import url("../plan/plan.css");
16	
17	:root {
18	  /* The wash behind the page's top — each festival's block sets its own. */
19	  --wash: light-dark(#e7e0fb, #1c1830);
20	  --wash-clear: light-dark(rgba(231, 224, 251, 0), rgba(28, 24, 48, 0));
21	  /* Each genre's accent, named once: its palette below takes it as --violet. */
22	  --genre-comedy: light-dark(#b8862b, #d7a340);
23	  --genre-film: light-dark(#1f6fb2, #5aa9e6);
24	  --genre-fringe: light-dark(#c2185b, #f06292);
25	  --genre-theatre: light-dark(#c4572e, #e8825a);
26	  /* A dot or stripe that names a festival anywhere else reads its genre's. */
27	  --colour-jerusalem-comedy: var(--genre-comedy);
28	  --colour-haifa-iff: var(--genre-film);
29	  --colour-edfringe: var(--genre-fringe);
30	  --colour-acco: var(--genre-theatre);
31	}
32	
33	[data-festival-colour="jerusalem-comedy"] {
34	  --festival-colour: var(--colour-jerusalem-comedy);
35	}
36	[data-festival-colour="haifa-iff"] {
37	  --festival-colour: var(--colour-haifa-iff);
38	}
39	[data-festival-colour="edfringe"] {
40	  --festival-colour: var(--colour-edfringe);
41	}
42	[data-festival-colour="acco"] {
43	  --festival-colour: var(--colour-acco);
44	}
45	
46	/* ---- the genres' palettes ---------------------------------------------- */
47	
48	:root[data-genre="comedy"] {
49	  /* Comedy: warm brass on sandstone, the house lights up — the accent the
50	     Fringe planner spends on violet. Kept to the same two-tone shape (a mid tone and
51	     a second for hover/active) so every rule in plan.css that reaches for
52	     --violet lands somewhere sensible without being restated here. In the dark
53	     the pair swaps direction: brass lifts towards the light rather than away
54	     from it, because the hover state has to stay the brighter of the two. */
55	  --wash: light-dark(#f1ddb6, #241d12);
56	  --wash-clear: light-dark(rgba(241, 221, 182, 0), rgba(36, 29, 18, 0));
57	  --violet: var(--genre-comedy);
58	  --violet-dark: light-dark(#94691d, #ecc06a);
59	  --ink: light-dark(#1d1a14, #f2e9da);
60	  --paper: light-dark(#ffffff, #221d16);
61	  --bg: light-dark(#faf7f0, #14110c);
62	  --muted: light-dark(#7a7160, #a89c86);
63	  --line: light-dark(#ece5d8, #37301f);
64	  /* light-dark() takes colours, not whole shadows — wrapping the lengths in it
65	     too makes every box-shadow that reads this token invalid, i.e. no shadow at
66	     all, in both themes. */
67	  --shadow-soft: 0 12px 30px light-dark(rgba(16, 24, 40, 0.08), rgba(0, 0, 0, 0.55));
68	  /* The "in your plan" pill, which plan.css paints as ink-on-wash. */
69	  --ok-text: light-dark(#047857, #6fe0ab);
70	  --ok-bg: light-dark(#e6f7ee, #123527);
71	}
72	
73	/* Film: the blue of a darkened auditorium lit by the screen. */
74	:root[data-genre="film"] {
75	  --wash: light-dark(#cde2f5, #0f1c28);
76	  --wash-clear: light-dark(rgba(205, 226, 245, 0), rgba(15, 28, 40, 0));
77	  --violet: var(--genre-film);
78	  --violet-dark: light-dark(#17568c, #8cc6f2);
79	  --ink: light-dark(#0e1a26, #e4eef7);
80	  --paper: light-dark(#ffffff, #14202c);
81	  --bg: light-dark(#f5f9fc, #0b141c);
82	  --muted: light-dark(#5d6f80, #8fa4b6);
83	  --line: light-dark(#dde8f1, #243646);
84	}
85	
86	/* The fringe: a flyposter magenta on slate, every genre at once. */
87	:root[data-genre="fringe"] {
88	  --wash: light-dark(#f7cde0, #2a1220);
89	  --wash-clear: light-dark(rgba(247, 205, 224, 0), rgba(42, 18, 32, 0));
90	  --violet: var(--genre-fringe);
91	  --violet-dark: light-dark(#961245, #f48fb1);
92	  --ink: light-dark(#1b1a22, #eeeaf2);
93	  --paper: light-dark(#ffffff, #1c1a22);
94	  --bg: light-dark(#f7f6f9, #111016);
95	  --muted: light-dark(#6b6878, #a19eb0);
96	  --line: light-dark(#e6e3ec, #302d3a);
97	}
98	
99	/* Theatre: the red of the curtain and the stage's warm boards. */
100	:root[data-genre="theatre"] {
101	  --wash: light-dark(#f6d3c1, #2a1812);
102	  --wash-clear: light-dark(rgba(246, 211, 193, 0), rgba(42, 24, 18, 0));
103	  --violet: var(--genre-theatre);
104	  --violet-dark: light-dark(#9c4322, #f2a585);
105	  --ink: light-dark(#23150f, #f6e7df);
106	  --paper: light-dark(#ffffff, #23160f);
107	  --bg: light-dark(#fcf7f4, #150d09);
108	  --muted: light-dark(#7d6559, #b09385);
109	  --line: light-dark(#f0e0d7, #3c2a21);
110	}
111	
112	/* ---- moving between festivals ------------------------------------------ */
113	
114	/* The theme's colours fade into the next festival's rather than jump. Only a
115	   registered custom property interpolates — an unregistered one is a string
116	   and flips at the end — so each token a palette above sets is registered as
117	   a colour, and the root transitions them. Every rule reading a token follows
118	   it frame by frame, and the page keeps responding throughout (a date handle
119	   being dragged included), which a snapshot cross-fade would not. The header
120	   declares its own values, so it holds still. */
121	@property --wash { syntax: "<color>"; inherits: true; initial-value: transparent; }
122	@property --wash-clear { syntax: "<color>"; inherits: true; initial-value: transparent; }
123	@property --violet { syntax: "<color>"; inherits: true; initial-value: transparent; }
124	@property --violet-dark { syntax: "<color>"; inherits: true; initial-value: transparent; }
125	@property --ink { syntax: "<color>"; inherits: true; initial-value: transparent; }
126	@property --paper { syntax: "<color>"; inherits: true; initial-value: transparent; }
127	@property --bg { syntax: "<color>"; inherits: true; initial-value: transparent; }
128	@property --muted { syntax: "<color>"; inherits: true; initial-value: transparent; }
129	@property --line { syntax: "<color>"; inherits: true; initial-value: transparent; }
130	
131	:root {
132	  transition: --wash 0.6s ease, --wash-clear 0.6s ease, --violet 0.6s ease, --violet-dark 0.6s ease, --ink 0.6s ease, --paper 0.6s ease, --bg 0.6s ease, --muted 0.6s ease, --line 0.6s ease;
133	}
134	
135	@media (prefers-reduced-motion: reduce) {
136	  :root { transition: none; }
137	}
138	
139	:root {
140	  /* The grid's palette, cut down to what this festival publishes: a night is on
141	     sale or it is free. The Fringe's sold-out / 2-for-1 / preview colours are
142	     left defined by the import and simply never drawn. */
143	  --fr-avail: light-dark(#2a9d8f, #35b6a6);
144	  --fr-free: light-dark(#1f9e55, #2fbd6a);
145	  --fr-ink: light-dark(#00243d, #f2e9da);
146	
147	  /* Hebrew, Japanese and Cyrillic: Inter carries the Cyrillic, and neither it
148	     nor Plus Jakarta Sans carries the other two scripts, so Heebo and Noto Sans
149	     JP go in front of both. A Latin string still renders in the site's own face
150	     — neither added font has Latin coverage worth preferring, so the fallback
151	     order decides, which is what we want. */
152	  --sans: "Inter", "Heebo", "Noto Sans JP", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
153	  --display: "Plus Jakarta Sans", "Heebo", "Noto Sans JP", "Inter", system-ui, sans-serif;
154	
155	  /* How many nights the grid spans. The Fringe planner's calendar is a fixed
156	     month; a festival's is exactly as long as its programme, and both the day
157	     header and every lane's track have to agree on the number. */
158	  --fest-days: 5;
159	}
160	
161	/* Every colour above picks its side with `light-dark()`, which reads the used
162	   colour scheme — so the whole dark theme is these two rules: the device asks
163	   for dark and the reader has not said otherwise, or the reader chose it. Light
164	   declares nothing, deliberately: `color-scheme` shifts how the page's own
165	   background composites by a unit per channel, and the light rendering is
166	   committed in the goldens. Declaring it only on the dark side also darkens the
167	   native select and time fields there, which is the rest of what it is for. */
168	@media (prefers-color-scheme: dark) {
169	  :root:not([data-theme="light"]) {
170	    color-scheme: dark;
171	  }
172	}
173	:root[data-theme="dark"] {
174	  color-scheme: dark;
175	}
176	
177	/* Hebrew needs a little more line height than the Latin faces are set for, or
178	   the nikud-less but tall letters clip in the dense grid rows. Japanese wants
179	   the same room for the same reason. */
180	[lang="he"] {
181	  font-family: "Heebo", var(--sans);
182	  line-height: 1.35;
183	}
184	[lang="ja"] {
185	  font-family: "Noto Sans JP", var(--sans);
186	  line-height: 1.4;
187	}
188	
189	/* A warm stone wash behind the page's top, so the festival reads as its own
190	   place without touching a single component. One gradient, no images. */
191	/* The Fringe planner caps its content at plan.css's --maxw; this page is a
192	   calendar first, and a wide screen is more days and hours in view, so it
193	   spans the window, header and footer included, to keep one set of edges. */
194	body.festival-page {
195	  --maxw: none;
196	}
197	
198	/* The page leaves the mouse cursor to the browser. plan.css, which this page
199	   imports whole, sets its own for the Fringe planner, so they are reverted to
200	   the browser's here rather than stripped from a stylesheet another page
201	   uses; !important because those rules are more specific than any reset. */
202	body.festival-page,
203	body.festival-page *,
204	body.festival-page *::before,
205	body.festival-page *::after {
206	  cursor: revert !important;
207	}
208	
209	body.festival-page {
210	  background: linear-gradient(180deg, var(--wash) 0%, var(--wash) 160px, var(--wash-clear) 560px), var(--bg);
211	}
212	
213	/* The leading festival's city, faded behind the top of the page
214	   (city-backdrop.js). It sits over the wash and under everything else — the
215	   body is no stacking context, so z-index -1 paints it just above the canvas
216	   the body's background is drawn on — and it thins out to nothing before the
217	   calendar, which is never drawn over a picture. Scrolls with the page. */
218	.city-backdrop {
219	  position: absolute;
220	  inset: 0 0 auto 0;
221	  height: 620px;
222	  z-index: -1;
223	  overflow: hidden;
224	  pointer-events: none;
225	  -webkit-mask-image: linear-gradient(180deg, #000 35%, transparent);
226	  mask-image: linear-gradient(180deg, #000 35%, transparent);
227	}
228	.city-backdrop img {
229	  position: absolute;
230	  inset: 0;
231	  width: 100%;
232	  height: 100%;
233	  object-fit: cover;
234	  opacity: 0;
235	  transition: opacity 0.6s ease;
236	}
237	.city-backdrop img.is-on {
238	  opacity: 0.45;
239	}
240	@media (prefers-reduced-motion: reduce) {
241	  .city-backdrop img { transition: none; }
242	}
243	
244	/* --- the grid's shape ---------------------------------------------------- */
245	
246	.days,
247	.lane-track {
248	  grid-template-columns: repeat(var(--fest-days), minmax(0, 1fr));
249	}
250	
251	/* Both belong to the Fringe's month-long calendar: a pre-festival shaded zone
252	   and JS-positioned weekend stripes. This grid is only the festival's own
253	   nights, and the weekend is already marked on the day header. */
254	.wknd-cols,
255	.festend {
256	  display: none;
257	}
258	
259	/* --- the browse stage ---------------------------------------------------- */
260	
261	/* The Fringe planner's empty board asks for a favourites file. There is no such
262	   export for this festival, so the empty board is the programme itself — which
263	   at this size is a better starting point than a search box anyway. */
264	.browse-stage {
265	  display: flex;
266	  flex-direction: column;
267	  gap: 8px;
268	  padding: 14px 16px 6px;
269	  overflow: hidden;
270	}
271	.browse-head {
272	  flex: 0 0 auto;
273	}
274	.browse-line1 {
275	  margin: 0;
276	  font-family: var(--display);
277	  font-weight: 700;
278	  font-size: 1.05rem;
279	}
280	.browse-line2 {
281	  margin: 2px 0 0;
282	  font-size: 0.82rem;
283	  color: var(--muted);
284	}
285	.browse-list {
286	  flex: 1 1 auto;
287	  margin: 0;
288	  padding: 0 4px 8px 0;
289	  list-style: none;
290	  overflow-y: auto;
291	  overscroll-behavior: contain;
292	}
293	
294	/* --- the reader's own two controls ---------------------------------------- */
295	
296	/* Language and theme sit at the end of the header: they belong to the reader
297	   rather than to the site, so they read as the last thing in the bar rather
298	   than as part of its identity. */
299	.chrome-prefs {
300	  display: inline-flex;
301	  align-items: center;
302	  gap: 6px;
303	  margin-inline-start: 10px;
304	}
305	.lang-select {
306	  height: 30px;
307	  padding: 0 8px;
308	  border: 1px solid var(--line);
309	  border-radius: 999px;
310	  background: var(--paper);
311	  color: var(--ink);
312	  font: inherit;
313	  font-size: 0.82rem;
314	  font-weight: 600;
315	}
316	.lang-select:hover,
317	.theme-toggle:hover {
318	  border-color: var(--violet);
319	  color: var(--violet-dark);
320	}
321	.theme-toggle {
322	  display: inline-flex;
323	  align-items: center;
324	  justify-content: center;
325	  width: 30px;
326	  height: 30px;
327	  padding: 0;
328	  border: 1px solid var(--line);
329	  border-radius: 999px;
330	  background: var(--paper);
331	  color: var(--ink);
332	}
333	/* The toggle shows the state a press would move to, which is the opposite of
334	   the one in force — so the icons swap with the theme, on the reader's choice
335	   or (with no choice made) on the device's. */
336	.theme-ico--sun {
337	  display: none;
338	}
339	@media (prefers-color-scheme: dark) {
340	  :root:not([data-theme="light"]) .theme-ico--sun {
341	    display: block;
342	  }
343	  :root:not([data-theme="light"]) .theme-ico--moon {
344	    display: none;
345	  }
346	}
347	:root[data-theme="dark"] .theme-ico--sun {
348	  display: block;
349	}
350	:root[data-theme="dark"] .theme-ico--moon {
351	  display: none;
352	}
353	
354	/* The Fringe planner's header is a three-column grid sized for a logo, a nav
355	   and one hint. This one carries two controls more, which is more than 390px
356	   of phone can hold in a row — so below the width where the festival's dates
357	   already drop out, the header becomes two rows and the nav takes the second.
358	   (The board below it is a 1174px grid and stays a desktop instrument; this is
359	   about the chrome not running off the edge on the way to it.) */
360	@media (max-width: 940px) {
361	  /* Flex rather than the imported grid: a grid column is shared down the rows,
362	     so the wordmark's width would set the nav's and push the controls off the
363	     edge — which is exactly what it did. */
364	  .header-inner {
365	    display: flex;
366	    flex-wrap: wrap;
367	    align-items: center;
368	    row-gap: 6px;
369	    column-gap: 12px;
370	  }
371	  .logo {
372	    flex: 1 1 100%;
373	  }
374	  .main-nav {
375	    gap: 20px;
376	  }
377	  .header-side {
378	    margin-inline-start: auto;
379	  }
380	}
381	
382	/* What the failed fetch actually said, under the line that says it failed.
383	   Untranslated on purpose — it is the network's words, not ours. */
384	.state-tech {
385	  margin: 4px 0 0;
386	  font-size: 0.78rem;
387	  color: var(--muted);
388	}
389	
390	/* --- the components the Fringe planner paints white ----------------------- */
391	
392	/* plan.css was written for one theme and spells those surfaces `#fff`. They are
393	   restated here against the token, which carries both themes, rather than
394	   duplicated into a dark-only block — a rule that reads the same in the light
395	   is a rule that cannot drift between the two. */
396	.site-header {
397	  background: color-mix(in srgb, var(--paper) 95%, transparent);
398	}
399	
400	/* The bar is the site's, not the festival's: it keeps the house palette
401	   plan.css defines whichever festival's block is in force on the root, so
402	   nothing in it moves when the reader picks another festival. plan.css has no
403	   dark side, so the dark half of each pair is set here. */
404	.site-header {
405	  --violet: light-dark(#6c4cf1, #a591ff);
406	  --violet-dark: light-dark(#5a3fd6, #c3b6ff);
407	  --ink: light-dark(#101828, #eceaf5);
408	  --paper: light-dark(#ffffff, #1a1826);
409	  --muted: light-dark(#667085, #a3a0b5);
410	  --line: light-dark(#eaecf0, #2e2b3d);
411	  /* Opaque, or the festival's wash behind the page's top tints it. */
412	  background: var(--paper);
413	  color: var(--ink);
414	}
415	.board-clear,
416	.btn-ghost,
417	.board-legend-btn,
418	.ss-bar,
419	.chip-trigger,
420	.panel-filter,
421	.opt-select,
422	.ctl-time,
423	.ctl-num,
424	.tmode,
425	.tmode-btn,
426	.meal-pill,
427	.sch-show,
428	.sch-pin,
429	.sch-emoji {
430	  background: var(--paper);
431	}
432	/* The light halves below are plan.css's own values, kept to the byte: this page
433	   is restating those rules to give them a dark half, not to restyle the light
434	   one. The schedule's own two-layer background is the exception that has to be
435	   left alone in the light and overridden only in the dark — restating it at all
436	   moves the antialiasing of its rounded corners, which the goldens hold. */
437	@media (prefers-color-scheme: dark) {
438	  :root:not([data-theme="light"]) .schedule-wrap {
439	    background:
440	      linear-gradient(var(--paper), var(--paper)) padding-box,
441	      repeating-linear-gradient(90deg, #2b251c 0 1px, transparent 1px 100%);
442	  }
443	}
444	:root[data-theme="dark"] .schedule-wrap {
445	  background:
446	    linear-gradient(var(--paper), var(--paper)) padding-box,
447	    repeating-linear-gradient(90deg, #2b251c 0 1px, transparent 1px 100%);
448	}
449	.sch-day--empty {
450	  background: repeating-linear-gradient(
451	    45deg,
452	    light-dark(#fbfbfd, #1b170f) 0 5px,
453	    light-dark(#f4f5f8, #231d14) 5px 10px
454	  );
455	}
456	.browse-list .ss-row,
457	.ss-results .ss-row {
458	  color: var(--ink);
459	}
460	/* The footer is the one band that is dark in both themes, so it cannot follow
461	   --ink (which flips) and states its own two. */
462	.site-footer {
463	  background: light-dark(#1d1a14, #0a0906);
464	  color: light-dark(#d9d9d9, #b6ac99);
465	}
466	.sch-day--empty .sch-day-head {
467	  background: light-dark(#f7f7fa, #1b170f);
468	}
469	.sch-day.wknd .sch-day-head {
470	  background: light-dark(#f4f2fe, #241d12);
471	}
472	
473	/* --- right to left -------------------------------------------------------- */
474	
475	/* The board's own geometry follows the page's direction on its own: the day
476	   columns, the lanes and the schedule's days are grid and flex tracks. What is
477	   left here is
478	   the handful of places plan.css states a physical side. */
479	[dir="rtl"] .ss-icon {
480	  left: auto;
481	  right: 12px;
482	}
483	[dir="rtl"] .ss-input {
484	  padding-left: 12px;
485	  padding-right: 40px;
486	}
487	/* The status stripe, and the padding that clears it, move to the other edge —
488	   with plan.css's own colour, which is the performance's status rather than
489	   the block's text. */
490	[dir="rtl"] .sch-show {
491	  border-left: 1px solid var(--line);
492	  border-right: 4px solid var(--seg, var(--violet));
493	  padding: 1px 9px 1px 4px;
494	}
495	[dir="rtl"] .schedule.cols-tiny .sch-show {
496	  padding-right: 5px;
497	  border-right-width: 3px;
498	  border-left-width: 1px;
499	}
500	[dir="rtl"] .sch-emoji {
501	  left: auto;
502	  right: -2px;
503	  transform: translate(50%, -50%);
504	}
505	[dir="rtl"] .lane-remove {
506	  right: auto;
507	  left: 4px;
508	}
