510	/* --- the version popup --------------------------------------------------- */
511	
512	/* Each front-end ships its own rules for the shared popup module (a stylesheet
513	   cannot be imported the way a module can) — except here, where the import
514	   above already brought the planner's in. Nothing to add. */
515	
516	/* --- the calendar leads ---------------------------------------------------
517	 *
518	 * plan.css draws a schedule block as one flat link: a stripe, a name, an hour.
519	 * Here a card is the draft's pick for its hour, and when other shows wanted
520	 * the hour too, a lane beside it draws each of them at its own times.
521	 * Everything else the page has to say about a card is in the popup, so a
522	 * calendar at rest reads as a calendar.
523	 */
524	.sch-slot { position: absolute; left: 3px; right: 3px; }
525	/* The pick leaves a band clear at its end edge for the lane. */
526	.sch-slot--contested .sch-show { inset-inline-end: 17px; }
527	.sch-show {
528	  position: absolute; inset: 0;
529	  flex-direction: column; justify-content: center; gap: 1px;
530	  padding: 3px 5px 3px 9px;
531	  overflow: hidden; z-index: 2;
532	  box-shadow: 0 2px 5px rgba(16, 24, 40, 0.1);
533	}
534	.sch-slot:hover .sch-show { box-shadow: 0 5px 14px rgba(16, 24, 40, 0.18); }
535	/* Only the name and its meta are the link out to the festival's own page. */
536	.sch-open {
537	  display: flex; flex-direction: column; gap: 1px; min-width: 0;
538	  text-decoration: none; color: var(--ink);
539	}
540	.sch-open:hover .sch-name { text-decoration: underline; }
541	.sch-show .sch-name { -webkit-line-clamp: 1; }
542	.sch-show:not(.sch-show--tight) .sch-name { -webkit-line-clamp: 2; }
543	
544	/* The lane is as tall as the slot, so it is one steady target; the bars it
545	   holds reach above and below it to the rivals' own starts and ends, and are
546	   painted through (pointer-events off) so the lane is the only thing hit. */
547	.sch-rivals {
548	  position: absolute; top: 0; bottom: 0; inset-inline-end: 0; width: 15px;
549	  padding: 0; border: 0; border-radius: 4px; background: transparent;
550	  z-index: 1;
551	}
552	.sch-rivals:hover, .sch-rivals[aria-expanded="true"] {
553	  background: color-mix(in srgb, var(--violet) 10%, transparent);
554	}
555	.sch-rivals:focus-visible { outline: 2px solid var(--violet); outline-offset: 1px; }
556	.sch-rival {
557	  --w: calc((13px - (var(--lanes) - 1) * 1px) / var(--lanes));
558	  position: absolute; pointer-events: none;
559	  top: var(--from); height: var(--len);
560	  inset-inline-start: calc(1px + var(--lane) * (var(--w) + 1px)); width: var(--w);
561	  border-radius: 3px;
562	  background: color-mix(in srgb, var(--violet) 30%, var(--paper));
563	  border: 1px dashed var(--violet);
564	  box-sizing: border-box;
565	}
566	.sch-rivals:hover .sch-rival, .sch-rivals[aria-expanded="true"] .sch-rival {
567	  background: color-mix(in srgb, var(--violet) 50%, var(--paper));
568	}
569	/* Too many to tell apart: one wash down the pick's slot, darkest where the
570	   most shows overlap (its stops are drawn in crowdWash), and a count. */
571	.sch-crowd { position: absolute; inset: 0; border-radius: 3px; pointer-events: none; }
572	.sch-rivals--crowd:hover .sch-crowd, .sch-rivals--crowd[aria-expanded="true"] .sch-crowd {
573	  box-shadow: inset 0 0 0 1px var(--violet);
574	}
575	/* Narrow columns give the lane less of the card; the tiniest merge its rows,
576	   since a bar a pixel or two wide says nothing. */
577	.schedule.cols-narrow .sch-slot--contested .sch-show { inset-inline-end: 10px; }
578	.schedule.cols-narrow .sch-rivals { width: 9px; }
579	.schedule.cols-narrow .sch-rival { --w: calc((7px - (var(--lanes) - 1) * 1px) / var(--lanes)); }
580	.schedule.cols-tiny .sch-slot--contested .sch-show { inset-inline-end: 6px; }
581	.schedule.cols-tiny .sch-rivals { width: 5px; }
582	.schedule.cols-tiny .sch-rival { --w: 5px; inset-inline-start: 0; border-width: 0; }
583	.schedule.cols-narrow .sch-rivals-count { display: none; }
584	/* On paper of its own, since under it the washes may be solid. */
585	.sch-rivals-count {
586	  position: absolute; top: 1px; inset-inline: 0; pointer-events: none;
587	  padding: 1px 0; border-radius: 3px;
588	  background: var(--paper); box-shadow: 0 0 0 1px var(--violet);
589	  font-size: 0.5rem; font-weight: 700; line-height: 1.2; text-align: center;
590	  color: var(--violet); font-variant-numeric: tabular-nums;
591	}
592	
593	/* A card the reader has fixed in place, and one they have favourited: the
594	   first is the stronger claim, so it takes the ring and the only badge a
595	   card's face ever carries. */
596	.sch-show--locked {
597	  border-color: var(--ok);
598	  box-shadow: inset 0 0 0 1.5px var(--ok), 0 2px 6px rgba(16, 24, 40, 0.1);
599	}
600	.sch-show--fav:not(.sch-show--locked) {
601	  box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--violet) 55%, transparent),
602	              0 2px 6px rgba(16, 24, 40, 0.08);
603	}
604	.sch-lock {
605	  position: absolute; top: 2px; inset-inline-end: 3px;
606	  font-size: 0.6rem; line-height: 1; pointer-events: none;
607	}
608	
609	/* --- the calendar's two floating surfaces --------------------------------- */
610	/* The card, not the calendar, is what they are positioned in — see placePop. */
611	.plan-result { position: relative; }
612	.cal-pop {
613	  position: absolute; z-index: 40; width: max-content; max-width: 300px;
614	  padding: 8px 10px; border-radius: 10px;
615	  background: var(--paper); border: 1px solid var(--line);
616	  box-shadow: 0 10px 26px rgba(16, 24, 40, 0.18);
617	  font-size: 0.7rem; line-height: 1.35; color: var(--ink);
618	}
619	.cal-pop .pop-title {
620	  margin: 0 0 2px; font-family: var(--display); font-weight: 700; font-size: 0.76rem;
621	}
622	.cal-pop .pop-lead { margin: 0 0 6px; color: var(--muted); font-size: 0.64rem; }
623	/* A show's popup leads with its picture, edge to edge across the top. */
624	.cal-pop--preview { width: 280px; }
625	.pop-art {
626	  margin: -8px -10px 8px;
627	  aspect-ratio: 16 / 9;
628	  overflow: hidden;
629	  border-radius: 10px 10px 0 0;
630	  background: color-mix(in srgb, var(--muted) 12%, var(--paper));
631	}
632	.pop-art:not(:first-child) { margin-top: 0; border-radius: 0; }
633	.pop-art img { display: block; width: 100%; height: 100%; object-fit: cover; }
634	.pop-art--emoji {
635	  aspect-ratio: 3 / 1;
636	  display: grid;
637	  place-items: center;
638	  background: color-mix(in srgb, var(--festival-colour, var(--violet)) 22%, var(--paper));
639	  font-size: 2.2rem;
640	  line-height: 1;
641	}
642	.cal-pop .pop-where { margin: 0 0 4px; color: var(--muted); font-size: 0.64rem; }
643	.cal-pop .pop-about {
644	  margin: 0 0 2px;
645	  display: -webkit-box;
646	  -webkit-line-clamp: 4;
647	  -webkit-box-orient: vertical;
648	  overflow: hidden;
649	}
650	.cal-pop .pop-link {
651	  display: inline-block;
652	  margin: 0 0 6px;
653	  color: var(--violet-dark, var(--violet));
654	  font-size: 0.64rem;
655	  font-weight: 600;
656	}
657	.cal-pop .pop-foot { margin: 6px 0 0; color: var(--muted); font-size: 0.62rem; }
658	.cal-pop .pop-more { margin: 4px 0 0; color: var(--muted); font-size: 0.66rem; }
659	.panel-more { margin: 6px 8px 2px; color: var(--muted); font-size: 0.72rem; line-height: 1.35; }
660	.pop-nights, .pop-rivals { list-style: none; margin: 0; padding: 0; display: grid; gap: 2px; }
661	.pop-night {
662	  display: flex; align-items: baseline; justify-content: space-between; gap: 10px;
663	  padding: 2px 6px; border-radius: 6px; font-variant-numeric: tabular-nums;
664	}
