file.content:
   grips and the travel pictures beside them, so neither ever covers a
   festival. */
.tl-track {
  --lane: 60px;
  position: relative;
  min-height: calc(36px + var(--lane));
}
.tl-period {
  position: absolute;
  top: -8px;
  bottom: 0;
  background: color-mix(in srgb, var(--violet) 14%, transparent);
  border-radius: 4px;
}
/* Today: a stick figure standing on the months' line, holding up a sign. It
   shifts about a little, and cheers when the reader makes a choice. */
.tl-today {
  position: absolute;
  bottom: -1px;
  width: 0;
  height: 0;
  color: var(--ink);
  z-index: 3;
  pointer-events: none;
}
.tl-dude {
  position: absolute;
  bottom: 0;
  left: -10px;
  overflow: visible;
}
.tl-sign {
  position: absolute;
  bottom: 33px;
  left: 6px;
  transform: translateX(-50%);
  transform-origin: 50% calc(100% + 10px);
  padding: 0 4px;
  border: 1.5px solid var(--ink);
  border-radius: 3px;
  background: var(--paper);
  font-size: 0.6rem;
  font-weight: 800;
  line-height: 12px;
  white-space: nowrap;
  animation: tl-sign-sway 3.2s ease-in-out infinite;
}
.tl-sign::after {
  content: "";
  position: absolute;
  top: 100%;
  left: 50%;
  width: 1.5px;
  height: 10px;
  margin-left: -0.75px;
  background: var(--ink);
}
.tl-dude .dude-arm {
  transform-box: view-box;
  transform-origin: 10px 12px;
  animation: tl-arm-swing 2.4s ease-in-out infinite;
}
.tl-dude .dude-leg {
  transform-box: view-box;
  transform-origin: 10px 21px;
  animation: tl-leg-tap 1.9s ease-in-out infinite;
}
.tl-today.is-cheering .tl-dude,
.tl-today.is-cheering .tl-sign {
  animation: tl-cheer 0.55s ease-out 2;
}
.tl-today.is-cheering .dude-arm {
  animation: tl-arm-cheer 1.1s ease-out 1;
}
@keyframes tl-sign-sway {
  0%, 100% { transform: translateX(-50%) rotate(-4deg); }
  50% { transform: translateX(-50%) rotate(4deg); }
}
@keyframes tl-arm-swing {
  0%, 100% { transform: rotate(-10deg); }
  50% { transform: rotate(12deg); }
}
@keyframes tl-leg-tap {
  0%, 70%, 100% { transform: rotate(0deg); }
  80% { transform: rotate(-8deg); }
}
@keyframes tl-cheer {
  0%, 100% { translate: 0 0; }
  40% { translate: 0 -5px; }
}
@keyframes tl-arm-cheer {
  0%, 100% { transform: rotate(0deg); }
  20%, 80% { transform: rotate(125deg); }
}
@media (prefers-reduced-motion: reduce) {
  .tl-sign,
  .tl-dude .dude-arm,
  .tl-dude .dude-leg,
  .tl-today.is-cheering .tl-dude,
  .tl-today.is-cheering .tl-sign,
  .tl-today.is-cheering .dude-arm {
    animation: none;
  }
}
.tl-item {
  position: absolute;
  display: flex;
  align-items: center;
  gap: 6px;
  height: 26px;
  padding: 0;
  border: 0;
  background: none;
  font: inherit;
  color: var(--ink);
  white-space: nowrap;
}
.tl-item--late {
  flex-direction: row-reverse;
}
.tl-bar {
  flex: 0 0 auto;
  height: 12px;
  border-radius: 6px;
  background: var(--muted);
}
.tl-item.is-empty .tl-bar {
  background: transparent;
  border: 2px solid var(--muted);
}
.tl-label {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--muted);
}
.tl-item:hover .tl-label,
.tl-item:focus-visible .tl-label {
  color: var(--ink);
}
.tl-item.is-focus .tl-bar {
  background: var(--violet);
  border-color: var(--violet);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--violet) 28%, transparent);
}
.tl-item.is-focus .tl-label {
  color: var(--violet-dark);
  font-weight: 800;
}
/* A city's pill: its flag at the middle, and inside a pill of several
   festivals each one's run as a shade of its own, darkest where most of them
   run at once. */
.tl-bar {
  position: relative;
}
.tl-item--bunch .tl-bar {
  height: 14px;
  border-radius: 7px;
  background: color-mix(in srgb, var(--muted) 35%, transparent);
  overflow: hidden;
}
.tl-run {
  position: absolute;
  top: 0;
  bottom: 0;
  background: color-mix(in srgb, var(--muted) 45%, transparent);
}
.tl-item--bunch.is-focus .tl-bar {
  background: color-mix(in srgb, var(--violet) 35%, transparent);
}
.tl-item--bunch.is-focus .tl-run {
  background: color-mix(in srgb, var(--violet) 45%, transparent);
}
.tl-flag {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 18px;
  height: 12px;
  transform: translate(-50%, -50%);
  border-radius: 2px;
  box-shadow: 0 0 0 1.5px var(--paper), 0 1px 3px color-mix(in srgb, var(--ink) 35%, transparent);
}
.tl-card-name {
  font-weight: 700;
}
.tl-none {
  margin: 4px 0;
  font-size: 0.85rem;
  color: var(--muted);
}

/* --- the trip: its band on the year, its dates, the flights either side ---- */

/* Each end of the trip's band is a handle: a line across the whole strip,
   months and all, with a grip at its middle to take hold of. */
.tl-handle {
  position: absolute;
  top: -26px;
  bottom: 0;
  /* Narrow, so a short trip's band still has room to be taken hold of
     between its two ends; the grip is wider than the line it sits on. */
  width: 10px;
  margin-inline-start: -5px;
  touch-action: none;
  z-index: 2;
}
.tl-handle::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 50%;
  width: 2px;
  margin-left: -1px;
  background: var(--violet);
}
/* The planner's own grip (plan.css's .win-edge pill, upright here): two white
   bars on a violet capsule, running along the line it grabs. */
.tl-grip {
  position: absolute;
  bottom: calc(var(--lane) / 2);
  left: 50%;
  width: 12px;
  height: 26px;
  transform: translate(-50%, 50%);
  border-radius: 7px;
  background-color: var(--violet);
  background-image: linear-gradient(#fff, #fff), linear-gradient(#fff, #fff);
  background-repeat: no-repeat;
  background-size: 1.5px 12px;
  background-position: 4px center, 7.5px center;
  box-shadow: 0 1px 4px rgba(16, 24, 40, 0.3);
  transition: transform 0.12s ease;
}
.tl-handle:hover .tl-grip,
.tl-handle:focus-visible .tl-grip {
  transform: translate(-50%, 50%) scale(1.12);
}
.tl-handle:focus-visible {
  outline: none;
}
.tl-handle:focus-visible .tl-grip {
  outline: 3px solid color-mix(in srgb, var(--violet) 45%, transparent);
  outline-offset: 1px;
}
/* The trip's length, above the band, over the months. */
.tl-length {
  position: absolute;
  top: -46px;
  transform: translateX(-50%);
  padding: 0 6px;
  border-radius: 8px;
  background: var(--paper);
  font-size: 0.72rem;
  font-weight: 800;
  line-height: 16px;
  color: var(--violet-dark);
  white-space: nowrap;
  z-index: 3;
}
[dir="rtl"] .tl-length {
  transform: translateX(50%);
}
/* Each end's day of the month, at the top of its line: the first day's to the
   line's start side, the last day's to its end side, so a short trip's two
   never meet. */
.tl-day {
  position: absolute;
  top: -30px;
  padding: 0 3px;
  border-radius: 6px;
  background: var(--paper);
  font-size: 0.68rem;
  font-weight: 800;
  line-height: 14px;
  color: var(--violet-dark);
  z-index: 3;
  pointer-events: none;
}
.tl-day--from {
  transform: translateX(calc(-100% - 3px));
}
.tl-day--to {
  transform: translateX(3px);
}
[dir="rtl"] .tl-day--from {
  transform: translateX(calc(100% + 3px));
}
[dir="rtl"] .tl-day--to {
  transform: translateX(-3px);
}
/* The way there and back: a large picture beside each end of the trip, just
   outside its line, the way out before the first day and home after the last.
   Until the reader says how they travel it keeps changing between the ways,
   which is what asks for the click; once said it holds still. */
.tl-way {
  position: absolute;
  bottom: calc(var(--lane) / 2);
  width: 52px;
  height: 52px;
  padding: 5px;
  border: 1.5px solid color-mix(in srgb, var(--violet) 35%, var(--line));
  border-radius: 14px;
  background: var(--paper);
  color: var(--violet);
  box-shadow: var(--shadow-soft);
  z-index: 2;
}
.tl-way[hidden] {
  display: none;
}
.tl-way--from {
  transform: translate(calc(-100% - 12px), 50%);
}
.tl-way--to {
  transform: translate(12px, 50%);
}
[dir="rtl"] .tl-way--from {
  transform: translate(calc(100% + 12px), 50%);
}
[dir="rtl"] .tl-way--to {
  transform: translate(-12px, 50%);
}
.tl-way.is-unsettled {
  border-style: dashed;
}
.tl-way:hover,
.tl-way:focus-visible {
  border-color: var(--violet);
  background: color-mix(in srgb, var(--violet) 8%, var(--paper));
}
.tl-way > svg,
.tl-way .arrive-icons {
  display: block;
  width: 100%;
  height: 100%;
}
.tl-way .arrive-icons {
  position: relative;
  opacity: 0.8;
}
.tl-way .arrive-icons > svg {
  width: 100%;
  height: 100%;
}
/* A plane heads along the reader's line: into the trip on the way out, away
   from it on the way home. */
.tl-way .way-fly {
  transform: rotate(90deg);
}
[dir="rtl"] .tl-way .way-fly {
  transform: rotate(-90deg);
}
[dir="rtl"] .tl-way .way-drive {
  transform: scaleX(-1);
}

/* The travel card, under the strip: where you live, how you travel, and once
   said, the answer and the flights for a flyer. */
.travel-head {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--violet);
}
.travel-said {
  margin: 0;
  font-weight: 700;
  color: var(--ink);
}
.travel-flights {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 10px;
  margin-top: 10px;
}
.origin-guess {
  margin: 6px 0 0;
  font-size: 0.78rem;
  color: var(--muted);
}
.flight {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: color-mix(in srgb, var(--violet) 5%, var(--paper));
  font-size: 0.85rem;
  min-width: 0;
}
.flight-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0 6px;
  min-width: 0;
}
.flight-plane {
  flex: 0 0 auto;
  color: var(--violet);
}
/* Taking off on the way out, coming home the other way. The plane points
   along the reader's line, so a right-to-left page turns it round too. */
.flight--out .way-fly {
  transform: rotate(45deg);
}
.flight--back .way-fly {
  transform: rotate(135deg);
}
[dir="rtl"] .flight--out .way-fly {
  transform: rotate(-45deg);
}
[dir="rtl"] .flight--back .way-fly {
  transform: rotate(-135deg);
}
[dir="rtl"] .flight .way-drive {
  transform: scaleX(-1);
}
.arrive-icons {
  position: relative;
  flex: 0 0 auto;
  width: 22px;
  height: 22px;
  color: var(--violet);
  opacity: 0.7;
}
.arrive-icons > svg {
  position: absolute;
  inset: 0;
  opacity: 0;
  animation: arrive-turn 8s ease-in-out infinite;
}
.arrive-icons > svg:first-child {
  opacity: 1;
}
.arrive-icons > .way-train {
  animation-delay: -6s;
}
.arrive-icons > .way-drive {
  animation-delay: -4s;
}
.arrive-icons > .way-local {
  animation-delay: -2s;
}
@keyframes arrive-turn {
  0%, 21% { opacity: 1; }
  25%, 96% { opacity: 0; }
  100% { opacity: 1; }
}
@media (prefers-reduced-motion: reduce) {
  .arrive-icons > svg {
    animation: none;
  }
}
.flight-title {
  font-weight: 800;
}
.flight-day {
  color: var(--muted);
  font-size: 0.78rem;
  white-space: nowrap;
}
.flight-note {
  margin: 0;
  color: var(--muted);
  font-size: 0.82rem;
}
.flight-route {
  margin: 0;
  display: flex;
  align-items: center;
  gap: 6px;
  font-weight: 800;
  letter-spacing: 0.04em;
}
.flight-from {
  width: 4.2em;
  font: inherit;
  text-transform: uppercase;
  text-align: center;
  padding: 2px 4px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--paper);
  color: var(--ink);
}
.flight-from[aria-invalid="true"] {
  border-color: #c0392b;
}
.flight-arrow {
  color: var(--muted);
}
[dir="rtl"] .flight-arrow {
  transform: scaleX(-1);
}
.flight-fare,
.flight-search {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 2px 6px;
  color: var(--ink);
  text-decoration: none;
}
.flight-search {
  color: var(--violet-dark);
  font-weight: 700;
  text-decoration: underline;
}
.flight-time,
.flight-price {
  font-weight: 800;
}
.flight-price {
  color: var(--violet-dark);
}
.flight-dot {
  color: var(--muted);
}
.flight-partner {
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--muted);
}
.flight-partner::after {
  content: " ↗";
}
.flight-change {
  align-self: flex-start;
  padding: 0;
  border: 0;
  background: none;
  font: inherit;
  font-size: 0.78rem;
  color: var(--violet-dark);
  text-decoration: underline;
}
.timeline .origin-card {
  margin: 12px 0 0;
}

/* --- what the pool holds -------------------------------------------------- */

.pool-note {
  margin: 0 0 10px;
  padding: 8px 12px;
  border-radius: 10px;
  background: color-mix(in srgb, var(--violet) 8%, var(--paper));
  font-size: 0.84rem;
}
.pool-line {
  margin: 2px 0;
}
.pool-line--out {
  color: var(--muted);
}

/* --- where the reader is coming from ------------------------------------- */

.origin-card {
  margin: 0 0 12px;
  padding: 12px 14px;
  border: 2px solid var(--violet);
  border-radius: 14px;
  background: var(--paper);
}
.origin-ask {
  margin: 0;
  font-family: var(--display);
  font-weight: 800;
  font-size: 1.02rem;
}
.origin-why {
  margin: 2px 0 10px;
  font-size: 0.82rem;
  color: var(--muted);
}
.origin-answers {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.origin-abroad {
  gap: 6px;
}
.origin-select {
  max-width: 190px;
}
.origin-skip {
  margin-top: 8px;
  padding: 0;
  border: 0;
  background: none;
  font: inherit;
  font-size: 0.8rem;
  color: var(--violet-dark);
  text-decoration: underline;
}
.origin-status {
  margin: 6px 0 0;
  font-size: 0.8rem;
  color: var(--muted);
}
.origin-status:empty {
  display: none;
}

/* --- a list too long to draw --------------------------------------------- */

.browse-more {
  padding: 8px 0 4px;
  text-align: center;
  font-size: 0.86rem;
  color: var(--muted);
}

/* A day of the period with nothing on it keeps the Fringe planner's sliver,
   which this page's wider columns would otherwise override: the day either
   side of a festival is for travelling, and is drawn as such. */
.sch-day.sch-day--empty {
  min-width: 30px;
}

/* The origin answers are sentences rather than pictures, so they sit in a row
   with their emoji beside the words. */
.origin-pick {
  flex-direction: row;
  align-items: center;
  max-width: none;
  padding: 8px 12px;
}
.origin-pick .pref-word {
  white-space: nowrap;
}

/* The show's name in the city's own language, beside the programme's. */
.ss-row-local {
  color: var(--muted);
  font-weight: 400;
}

/* A phone: the year's month names every third month, smaller travel
 * pictures, and the country list inside its card. */
@media (max-width: 620px) {
  .tl-month:not(:nth-child(3n + 1)) {
    font-size: 0;
  }
  .tl-way {
    width: 40px;
    height: 40px;
    padding: 4px;
  }
  .origin-abroad {
    flex-wrap: wrap;
    max-width: 100%;
  }
  .origin-select {
    max-width: 100%;
    min-width: 0;
  }
}

/* A show's edge is its festival's colour, and its kind leads its name; a free
   show says so in a tag rather than in the edge. */
.sch-show { --seg: var(--festival-colour, var(--violet)); }
.sch-kind {
  margin-inline-end: 3px;
  font-size: 0.7rem;
}
/* Pinned to the card's end corner rather than set in the meta line, so a short
   card keeps its one line for the name. */
.sch-free {
  position: absolute;
  bottom: 2px;
  inset-inline-end: 3px;
  padding: 0 5px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--ok) 16%, var(--paper));
  color: var(--ink);
  font-size: 0.58rem;
  font-weight: 700;
  line-height: 1.5;
}
.fest-legend {
  display: flex;
  width: fit-content;
  flex-wrap: wrap;
  gap: 4px 14px;
  padding: 8px 4px 0;
  color: var(--muted);
  font-size: 0.72rem;
  font-weight: 600;
}
.fest-legend-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

