1	"use strict";
2	const { jerusalemReady } = require("../../shared/case-helpers");
3	
4	/* Every element's computed cursor, read at rest and again while the pointer
5	 * rests on each of the places that used to change it, against the cursor the
6	 * browser gives that same element with the page's own stylesheets switched
7	 * off: the hand on a link, the arrow on a button, auto elsewhere. */
8	const HOVERED = [".tl-handle--from", ".sch-body", ".sch-show"];
9	
10	const changed = (page) =>
11	  page.evaluate(() => {
12	    const els = [...document.querySelectorAll("*")];
13	    const styled = els.map((el) => getComputedStyle(el).cursor);
14	    const sheets = [...document.styleSheets];
15	    for (const sheet of sheets) sheet.disabled = true;
16	    const own = els.map((el) => getComputedStyle(el).cursor);
17	    for (const sheet of sheets) sheet.disabled = false;
18	    return els
19	      .map((el, i) => [el, styled[i], own[i]])
20	      .filter(([, cursor, browsers]) => cursor !== browsers)
21	      .map(([el, cursor, browsers]) => `${el.tagName.toLowerCase()}.${[...el.classList].join(".")}: ${cursor}, not ${browsers}`);
22	  });
23	
24	module.exports = {
25	  description: "the planner never changes the mouse cursor",
26	  page: "/planNG/?festival=jerusalem-comedy",
27	  viewport: "desktop",
28	  async verify(page, { origin, assert }) {
29	    await page.goto(`${origin}/planNG/?festival=jerusalem-comedy`, { waitUntil: "load" });
30	    await jerusalemReady(page);
31	
32	    assert.deepEqual(await changed(page), [], "no element sets a cursor");
