1	"use strict";
2	const { plannerReady } = require("../../shared/case-helpers");
3	
4	/* The harness lands every animation on its end state at once; this wraps that
5	 * stub to record what the calendar asked to animate, and on which block. The
6	 * day's end is moved earlier (shows leave) and back (shows come back). */
7	const RECORD = `
8	  window.__motion = [];
9	  const landed = Element.prototype.animate;
10	  Element.prototype.animate = function (keyframes, options) {
11	    if (this.closest && this.closest("#scheduleWrap")) {
12	      const first = Array.isArray(keyframes) ? keyframes[0] : keyframes;
13	      window.__motion.push({
14	        what: this.classList.contains("sch-ghost") ? "leave" : this.classList.contains("sch-day") ? "width" : "block",
15	        from: JSON.stringify(first),
16	      });
17	    }
18	    return landed.call(this, keyframes, options);
19	  };
20	`;
21	
22	async function moveDayEnd(page) {
23	  const line = page.locator(".sch-dayline--end");
24	  await line.focus();
25	  await page.evaluate(() => (window.__motion = []));
26	  for (let i = 0; i < 12; i++) await page.keyboard.press("ArrowUp");
27	  const out = await page.evaluate(() => window.__motion);
28	  await page.evaluate(() => (window.__motion = []));
29	  for (let i = 0; i < 12; i++) await page.keyboard.press("ArrowDown");
30	  const back = await page.evaluate(() => window.__motion);
31	  return { out, back };
32	}
33	
34	module.exports = {
35	  description: "shows the calendar gains or loses fade in or out, and the ones that move slide",
36	  page: "/planNG/?festival=haifa-iff",
37	  viewport: "desktop",
38	  async verify(page, { origin, assert }) {
39	    await page.addInitScript(RECORD);
40	    await page.goto(`${origin}/planNG/?festival=haifa-iff`, { waitUntil: "load" });
41	    await plannerReady(page, "haifa-iff");
